CREATE TABLE IF NOT EXISTS subscription_plans(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,duration_days SMALLINT UNSIGNED NOT NULL,price_toman INT UNSIGNED NOT NULL DEFAULT 0,features TEXT NULL,max_clinics SMALLINT UNSIGNED NULL,max_secretaries SMALLINT UNSIGNED NULL,highlight TINYINT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX plan_order(active,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS discount_codes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,title VARCHAR(190) NOT NULL DEFAULT '',scope VARCHAR(20) NOT NULL DEFAULT 'subscription',kind VARCHAR(10) NOT NULL DEFAULT 'percent',value INT UNSIGNED NOT NULL,max_discount_toman INT UNSIGNED NULL,min_amount_toman INT UNSIGNED NOT NULL DEFAULT 0,max_uses INT UNSIGNED NULL,per_owner_limit SMALLINT UNSIGNED NOT NULL DEFAULT 1,doctor_id BIGINT UNSIGNED NULL,plan_id INT UNSIGNED NULL,starts_at DATETIME NULL,ends_at DATETIME NULL,active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(plan_id) REFERENCES subscription_plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS discount_redemptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code_id INT UNSIGNED NOT NULL,order_type VARCHAR(20) NOT NULL,order_id BIGINT UNSIGNED NOT NULL,owner_key VARCHAR(40) NOT NULL,amount_toman INT UNSIGNED NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'reserved',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY redemption_order(order_type,order_id),INDEX redemption_code(code_id,status),FOREIGN KEY(code_id) REFERENCES discount_codes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS subscription_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,number VARCHAR(30) NULL UNIQUE,doctor_id BIGINT UNSIGNED NOT NULL,plan_id INT UNSIGNED NOT NULL,plan_name VARCHAR(120) NOT NULL,duration_days SMALLINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,base_toman INT UNSIGNED NOT NULL,credit_toman INT UNSIGNED NOT NULL DEFAULT 0,discount_code_id INT UNSIGNED NULL,discount_toman INT UNSIGNED NOT NULL DEFAULT 0,vat_percent DECIMAL(5,2) NOT NULL DEFAULT 0,vat_toman INT UNSIGNED NOT NULL DEFAULT 0,payable_toman INT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'proforma',payment_method VARCHAR(20) NULL,payment_tx_id BIGINT UNSIGNED NULL,offline_reference VARCHAR(100) NULL,period_start DATE NULL,period_end DATE NULL,expires_at DATETIME NOT NULL,created_by_user BIGINT UNSIGNED NULL,created_by_admin BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,paid_at DATETIME NULL,INDEX order_doctor(doctor_id,status),INDEX order_paid(status,paid_at),FOREIGN KEY(doctor_id) REFERENCES doctors(id),FOREIGN KEY(plan_id) REFERENCES subscription_plans(id),FOREIGN KEY(discount_code_id) REFERENCES discount_codes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoice_counters(year SMALLINT UNSIGNED PRIMARY KEY,last_number INT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purpose VARCHAR(20) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,gateway VARCHAR(20) NOT NULL,amount_toman INT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'initiated',order_code VARCHAR(40) NOT NULL UNIQUE,gateway_token VARCHAR(190) NULL,ref_num VARCHAR(100) NULL,card_mask VARCHAR(40) NULL,test_mode TINYINT NOT NULL DEFAULT 0,user_id BIGINT UNSIGNED NULL,doctor_id BIGINT UNSIGNED NULL,description VARCHAR(255) NOT NULL DEFAULT '',error VARCHAR(255) NULL,ip VARCHAR(45) NULL,callback_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,redirected_at DATETIME NULL,verified_at DATETIME NULL,UNIQUE KEY tx_token(gateway,gateway_token),UNIQUE KEY tx_ref(gateway,ref_num),INDEX tx_reference(purpose,reference_id),INDEX tx_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notice_markers(dedupe_key VARCHAR(160) PRIMARY KEY,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX notice_age(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
